//! Deterministic LaTeX writer for F15 [`Writeup`] documents (`00-overview.md` 2.13).
//!
//! Output is clean, compilable LaTeX compatible with `research_tools::tex_audit` and paired
//! with a `.bib` file generated by [`crate::writeup_bib::render_bibtex`]. Zero model calls.

use crate::writeup::{
    filter_verified_quotes, writeup_wording, ProseBasis, RejectedWriteupQuote, Writeup,
    WriteupBlock, WriteupOptions,
};
use ledger::Event;
use research_tools::sandbox::WorkspaceSandbox;
use std::fmt::Write as _;

/// Render a validated [`Writeup`] to LaTeX source.
///
/// The status line, optional coverage paragraph, and "How each statement was checked" table
/// are always emitted regardless of `opts.include_inline_badges`.
pub fn render_writeup_tex(doc: &Writeup, opts: &WriteupOptions) -> Result<String, String> {
    doc.validate()?;
    let mut out = String::new();
    let check_rows = doc.derived_check_table();

    out.push_str("\\documentclass[11pt]{article}\n");
    out.push_str("\\usepackage[utf8]{inputenc}\n");
    out.push_str("\\usepackage{amsmath,amssymb,booktabs,hyperref}\n\n");
    let _ = writeln!(out, "\\title{{{}}}", escape_latex(&doc.title));
    out.push_str("\\date{}\n\n");
    out.push_str("\\begin{document}\n");
    out.push_str("\\maketitle\n\n");

    // Mandatory status line (cannot be turned off; `00-overview.md` 2.13 rule 1 & 8.3 Q10).
    let _ = writeln!(
        out,
        "\\noindent\\textbf{{{}:}} {}\\\\",
        escape_latex(writeup_wording::STATUS_LABEL),
        escape_latex(&doc.status_line)
    );
    if doc.prose_edited_by_model {
        let _ = writeln!(
            out,
            "\\noindent\\textit{{{}}}\\\\",
            escape_latex(writeup_wording::PROSE_EDITED_BY_MODEL)
        );
    }
    out.push('\n');

    for sec in &doc.sections {
        let _ = writeln!(out, "\\section{{{}}}", escape_latex(&sec.title));
        if let Some(lbl) = sec.label.as_deref().map(str::trim).filter(|s| !s.is_empty()) {
            let _ = writeln!(out, "\\label{{{}}}", sanitize_label(lbl));
        }
        out.push('\n');

        for blk in &sec.blocks {
            match blk {
                WriteupBlock::Prose { text, basis } => {
                    let escaped = escape_latex(text);
                    if *basis == ProseBasis::Model && opts.include_inline_badges {
                        let _ = writeln!(
                            out,
                            "{escaped} \\textit{{{}}}\n",
                            escape_latex(writeup_wording::MODEL_SUFFIX)
                        );
                    } else {
                        let _ = writeln!(out, "{escaped}\n");
                    }
                }
                WriteupBlock::Formula {
                    latex,
                    handle,
                    label,
                } => {
                    let _ = writeln!(out, "% handle: {}", sanitize_comment(handle));
                    if let Some(lbl) = label.as_deref().map(str::trim).filter(|s| !s.is_empty()) {
                        out.push_str("\\begin{equation}\n");
                        let _ = writeln!(out, "\\label{{{}}}", sanitize_label(lbl));
                        let _ = writeln!(out, "{}", latex.trim());
                        out.push_str("\\end{equation}\n\n");
                    } else {
                        out.push_str("\\[\n");
                        let _ = writeln!(out, "{}", latex.trim());
                        out.push_str("\\]\n\n");
                    }
                }
                WriteupBlock::Quote(q) => {
                    let loc = escape_latex(&q.locator.display_text());
                    let ocr_suffix = if q.ocr {
                        format!(" {}", escape_latex(writeup_wording::OCR_TAG))
                    } else {
                        String::new()
                    };
                    out.push_str("\\begin{quote}\n");
                    let _ = writeln!(out, "{}", escape_latex(&q.text));
                    out.push_str("\\end{quote}\n");
                    let _ = writeln!(out, "\\noindent --- \\cite{{{}}} ({loc}){ocr_suffix}\n", q.cite_key);
                }
                WriteupBlock::Statement {
                    id,
                    text,
                    how_checked,
                    ..
                } => {
                    let badge_str = if opts.include_inline_badges {
                        format!(" [{}]", escape_latex(how_checked.label()))
                    } else {
                        String::new()
                    };
                    let _ = writeln!(
                        out,
                        "\\noindent\\textbf{{{}}}{badge_str}: {}\n",
                        escape_latex(id),
                        escape_latex(text)
                    );
                }
            }
        }
    }

    // Mandatory Explore coverage paragraph ("Where I looked"), cannot be omitted when present.
    if let Some(cov) = doc
        .coverage_paragraph
        .as_deref()
        .map(str::trim)
        .filter(|s| !s.is_empty())
    {
        let _ = writeln!(
            out,
            "\\section*{{{}}}\n\n{}\n",
            escape_latex(writeup_wording::COVERAGE_HEADING),
            escape_latex(cov)
        );
    }

    // Mandatory table "How each statement was checked" (cannot be omitted; `00-overview.md` 8.3 Q10).
    let _ = writeln!(
        out,
        "\\section*{{{}}}\n",
        escape_latex(writeup_wording::CHECK_TABLE_HEADING)
    );
    out.push_str("\\begin{tabular}{p{0.18\\linewidth}p{0.28\\linewidth}p{0.46\\linewidth}}\n");
    out.push_str("\\toprule\n");
    out.push_str("Step / Claim & How checked & Rests on \\\\\n");
    out.push_str("\\midrule\n");
    if check_rows.is_empty() {
        out.push_str("\\multicolumn{3}{l}{No statements recorded.} \\\\\n");
    } else {
        for row in &check_rows {
            let rests = if row.rests_on.is_empty() {
                "---".to_string()
            } else {
                escape_latex(&row.rests_on.join(", "))
            };
            let badge = escape_latex(&row.badge_text());
            let mut detail = rests;
            if let Some(note) = row.note.as_deref().map(str::trim).filter(|s| !s.is_empty()) {
                detail = format!("{detail} ({})", escape_latex(note));
            }
            let _ = writeln!(
                out,
                "{} & {} & {} \\\\",
                escape_latex(&row.id),
                badge,
                detail
            );
        }
    }
    out.push_str("\\bottomrule\n");
    out.push_str("\\end{tabular}\n\n");

    if !doc.bibliography.is_empty() {
        let stem = opts.bib_stem.trim();
        let stem = if stem.is_empty() { "references" } else { stem };
        out.push_str("\\bibliographystyle{plain}\n");
        let _ = writeln!(out, "\\bibliography{{{stem}}}\n");
    }

    out.push_str("\\end{document}\n");
    Ok(out)
}

/// Filter quotes through F4 `quote_core` first (dropping any unmatched quote) and render LaTeX.
pub fn render_verified_writeup_tex(
    doc: &Writeup,
    sandbox: &WorkspaceSandbox,
    session_id: &str,
    session_events: &[Event],
    opts: &WriteupOptions,
) -> Result<(String, Vec<RejectedWriteupQuote>), String> {
    let (cleaned, rejected) = filter_verified_quotes(doc, sandbox, session_id, session_events);
    let tex = render_writeup_tex(&cleaned, opts)?;
    Ok((tex, rejected))
}

/// Escape plain text for safe LaTeX output.
pub fn escape_latex(s: &str) -> String {
    let mut out = String::with_capacity(s.len());
    for ch in s.chars() {
        match ch {
            '\\' => out.push_str("\\textbackslash{}"),
            '{' => out.push_str("\\{"),
            '}' => out.push_str("\\}"),
            '$' => out.push_str("\\$"),
            '&' => out.push_str("\\&"),
            '#' => out.push_str("\\#"),
            '%' => out.push_str("\\%"),
            '_' => out.push_str("\\_"),
            '^' => out.push_str("\\textasciicircum{}"),
            '~' => out.push_str("\\textasciitilde{}"),
            '\r' => {}
            _ => out.push(ch),
        }
    }
    out
}

fn sanitize_label(s: &str) -> String {
    s.chars()
        .filter(|c| c.is_ascii_alphanumeric() || matches!(c, ':' | '-' | '_' | '.'))
        .collect()
}

fn sanitize_comment(s: &str) -> String {
    s.chars()
        .filter(|c| !matches!(c, '\r' | '\n'))
        .collect()
}
